  `precio` int NOT NULL,
  `fecha_ingreso` date DEFAULT NULL,
  `fecha_cobro` date DEFAULT NULL,
  `cliente_id_id` bigint NOT NULL,
  `fecha_venta` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `emprendimientos_pren_cliente_id_id_82fdeb37_fk_emprendim` (`cliente_id_id`),
  CONSTRAINT `emprendimientos_pren_cliente_id_id_82fdeb37_fk_emprendim` FOREIGN KEY (`cliente_id_id`) REFERENCES `emprendimientos_clientes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
