--
-- Table structure for table `ingresos_prendas`
--

DROP TABLE IF EXISTS `ingresos_prendas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ingresos_prendas` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `descripcion` varchar(100) NOT NULL,
  `precio` int NOT NULL,
  `cobrada` tinyint(1) DEFAULT NULL,
  `fecha_cobro` date DEFAULT NULL,
  `fecha_ingreso` date DEFAULT NULL,
  `fecha_venta` date DEFAULT NULL,
  `cliente_id_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ingresos_prendas_cliente_id_id_53011690_fk_ingresos_clientes_id` (`cliente_id_id`),
  CONSTRAINT `ingresos_prendas_cliente_id_id_53011690_fk_ingresos_clientes_id` FOREIGN KEY (`cliente_id_id`) REFERENCES `ingresos_clientes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8771 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

